import * as React from "react";

export type SpeakerBoxIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function SpeakerBoxIcon({ size = 20, ...props }: SpeakerBoxIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="7" width="9" height="10" rx="1.5" /><circle cx="8" cy="12" r="2.5" />
    </svg>
  );
}
